curl -X POST https://api.telegent.com/v1.0/distributor/create \
  -H 'Authorization: Bearer YOUR_TOKEN' \
  -H 'Content-Type: application/json' \
  -d '{
    "DistributorName": "Telegent Distributor 2",
    "BillingAddress": {
      "Street1": "",
      "City": "",
      "State": "",
      "Zip": ""
    }
  }'

curl -X POST https://api.telegent.com/v1.0/distributor/update \
  -H 'Authorization: Bearer YOUR_TOKEN' \
  -H 'Content-Type: application/json' \
  -d '{
    "DistributorId": "DID-eab92510-1040-45a5-bb9c-0bad9272f89d",
    "DistributorName": "Telegent Distributor 2.1",
    "BillingAddress": {"Street1": "", "Street2": "", "City": "", "State": "", "Zip": "", "Country": ""},
    "MailingAddress": {"Street1": "", "Street2": "", "City": "", "State": "", "Zip": "", "Country": ""}
  }'

curl -X POST https://api.telegent.com/v1.0/account/create \
  -H 'Authorization: Bearer YOUR_TOKEN' \
  -H 'Content-Type: application/json' \
  -d '{
    "AccountName": "Telegent Account 3",
    "AccountAdmin": "jerome@joonto.com",
    "BillingAddress": {
      "Street1": "Street 1",
      "City": "Heber",
      "State": "Utah"
    }
  }'

curl -X POST https://api.telegent.com/v1.0/account/update \
  -H 'Authorization: Bearer YOUR_TOKEN' \
  -H 'Content-Type: application/json' \
  -d '{
    "AccountName": "Telegent Account 3.1",
    "BillingAddress": {
      "Street1": "Street 1",
      "City": "Heber"
    }
  }'

curl -X POST https://api.telegent.com/v1.0/numbers/data-usage/update-renewal-info \n  -H 'Authorization: Bearer YOUR_TOKEN' \n  -H 'Content-Type: application/json' \n  -d '{
    "PhoneNumbers": [
      { "Number": "+18014730876" }
    ],
    "ResetUsage": false,
    "AutoRenew": true,
    "PeriodType": "M",
    "PeriodValue": 1,
    "RenewalDay": 1
  }'
